package au.aumanet.app;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import org.json.*;

/** Private bounded history; no automatic export, network publication, or GPS capture. */
final class LinkBenchmarkHistory {
    static final int LIMIT=100,MAX_FILE=2*1024*1024,MAX_RESULT=16384;
    private final File file;private JSONArray rows=new JSONArray();private boolean unavailable;
    LinkBenchmarkHistory(File file){this.file=file;try{if(file.exists()){if(file.length()>MAX_FILE)throw new IOException();String text=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);JSONTokener parser=new JSONTokener(text);Object raw=parser.nextValue();if(!(raw instanceof JSONArray)||parser.nextClean()!=0||((JSONArray)raw).length()>LIMIT)throw new IOException();JSONArray list=(JSONArray)raw;if(!text.equals(list.toString()))throw new IOException();for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);if(!"aumanet.link-benchmark-result.v1".equals(r.getString("schema"))||r.toString().getBytes(StandardCharsets.UTF_8).length>MAX_RESULT||!r.getString("id").matches("[a-f0-9]{32}")||!r.getString("errorCode").matches("[A-Z_0-9]{0,80}")||!java.util.Arrays.asList("complete","failed","cancelled").contains(r.getString("status")))throw new IOException();}rows=list;}}catch(Exception corrupt){unavailable=true;}}
    synchronized boolean available(){return !unavailable;}
    synchronized JSONArray snapshot()throws Exception{return new JSONArray(rows.toString());}
    synchronized void append(JSONObject result)throws Exception{
        if(unavailable)throw new IOException("Benchmark history is unavailable");if(result.toString().getBytes(StandardCharsets.UTF_8).length>MAX_RESULT)throw new IOException("Benchmark result bound reached");JSONArray next=new JSONArray();for(int i=Math.max(0,rows.length()-LIMIT+1);i<rows.length();i++)next.put(rows.getJSONObject(i));next.put(new JSONObject(result.toString()));byte[] bytes=next.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_FILE)throw new IOException("Benchmark history bound reached");File parent=file.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException();File temp=new File(parent,file.getName()+".pending");
        try{try(FileOutputStream out=new FileOutputStream(temp)){out.write(bytes);out.getFD().sync();}Files.move(temp.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);rows=next;}catch(Exception failure){unavailable=true;throw new IOException("Benchmark history write was not confirmed",failure);}
    }
    synchronized String export(String format)throws Exception{
        if(unavailable)throw new IOException("Benchmark history is unavailable");if(format.equals("json"))return new JSONObject().put("schema","aumanet.link-benchmark-export.v1").put("measurement","Phone-to-phone application payload goodput, not raw RF maximum").put("results",snapshot()).toString(2);
        if(!format.equals("csv"))throw new IOException("Invalid benchmark export format");StringBuilder csv=new StringBuilder("id,groupId,selfId,peerId,startedAt,completedAt,status,observationBoundary,uploadReceivedBytes,uploadElapsedMs,uploadBitsPerSecond,uploadComplete,downloadReceivedBytes,downloadElapsedMs,downloadBitsPerSecond,downloadComplete,phoneSeparationMeters,ownLatitude,ownLongitude,ownAccuracyMeters,ownAgeMs,ownTimestamp,ownMock,peerLatitude,peerLongitude,peerAccuracyMeters,peerAgeMs,peerTimestamp,peerMock,receiverNodeId,transmitterNodeId,radioStatus,rssiDbm,direction,verification,readAgeMs,relayAgeMs,sampleAgeKnown,errorCode,observationKind,configNodeId,configSourceRun,configObservationId,configVerification,configRole,configCatalogVersion,configStatus,configCurrentOptionId,configPersistedOptionId,configActualOptionId,configTrialTargetOptionId,configOperatingChannel,configOperatingClass,configBandwidthMHz,configCenterFrequencyHz,configConfiguredTxPowerDbm,configGeneration,configTransactionId,configAssociated,configPersistenceKnown,configReportAgeMs,configObservedElapsedMs,configTrialRemainingMs,testProfile\r\n");
        for(int i=0;i<rows.length();i++){
            JSONObject r=rows.getJSONObject(i),u=r.optJSONObject("upload"),d=r.optJSONObject("download");
            for(String boundary:new String[]{"start","end"}){
                String label=boundary;JSONObject metadata=r.optJSONObject(boundary.equals("start")?"observationsAtStart":"observationsAtEnd");if(metadata==null){if(boundary.equals("start")||r.has("observationsAtStart"))continue;metadata=r;label="snapshot";}
                JSONObject positions=metadata.optJSONObject("positions"),own=positions==null?null:positions.optJSONObject("own"),peer=positions==null?null:positions.optJSONObject("peer");JSONArray radio=metadata.optJSONArray("radioSignals");int n=radio==null?0:radio.length();JSONArray configurations=metadata.optJSONArray("radioConfigurations");int cn=configurations==null?0:configurations.length();
                for(int j=0;j<Math.max(1,n+cn);j++){
                    JSONObject signal=j<n?radio.getJSONObject(j):null;JSONObject configuration=j>=n&&j<n+cn?configurations.getJSONObject(j-n):null;JSONObject operating=actual(configuration);Object[] values={r.optString("id"),r.optString("groupId"),r.optString("selfId"),r.optString("peerId"),value(r,"startedAt"),value(r,"completedAt"),r.optString("status"),label,value(u,"receivedBytes"),value(u,"elapsedMs"),value(u,"goodputBitsPerSecond"),value(u,"complete"),value(d,"receivedBytes"),value(d,"elapsedMs"),value(d,"goodputBitsPerSecond"),value(d,"complete"),value(metadata,"phoneSeparationMeters"),value(own,"latitude"),value(own,"longitude"),value(own,"accuracy"),value(own,"ageMs"),value(own,"timestamp"),value(own,"mock"),value(peer,"latitude"),value(peer,"longitude"),value(peer,"accuracy"),value(peer,"ageMs"),value(peer,"timestamp"),value(peer,"mock"),value(signal,"receiverNodeId"),value(signal,"transmitterNodeId"),value(signal,"status"),value(signal,"rssiDbm"),value(signal,"direction"),value(signal,"verification"),value(signal,"readAgeMs"),value(signal,"relayAgeMs"),value(signal,"sampleAgeKnown"),r.optString("errorCode"),configuration!=null?"radio-configuration":signal!=null?"radio-signal":"metadata",value(configuration,"nodeId"),value(configuration,"sourceRun"),value(configuration,"observationId"),value(configuration,"verification"),value(configuration,"role"),value(configuration,"catalogVersion"),value(configuration,"status"),value(configuration,"currentOptionId"),value(configuration,"persistedOptionId"),value(configuration,"actualOptionId"),value(configuration,"trialTargetOptionId"),value(operating,"channel"),value(operating,"operatingClass"),value(operating,"bandwidthMHz"),value(operating,"centerFrequencyHz"),value(configuration,"configuredTxPowerDbm"),value(configuration,"nodeConfigGeneration"),value(configuration,"transactionId"),value(configuration,"associated"),value(configuration,"persistenceKnown"),value(configuration,"reportAgeMs"),value(configuration,"observedElapsedMs"),value(configuration,"trialRemainingMs"),value(r,"testProfile")};
                    for(int k=0;k<values.length;k++){if(k>0)csv.append(',');csv.append('"').append(String.valueOf(values[k]).replace("\"","\"\"")).append('"');}csv.append("\r\n");
                }
            }
        }return csv.toString();
    }
    private static JSONObject actual(JSONObject configuration)throws Exception{if(configuration==null||configuration.optInt("catalogVersion",0)!=1||!configuration.optBoolean("associated",false))return null;int id=configuration.optInt("actualOptionId",0);return id>=1&&id<=23?GatewayRadioConfigCodec.option(id):null;}
    private static Object value(JSONObject object,String key){return object==null||!object.has(key)||object.isNull(key)?"":object.opt(key);}
}
